        mov     bx, [motext__chunkSplit__d]
        shl     bx, 1                       ; word elements
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     [es:bx], ax
; ---- chunkUsed[c] = halfChunk
        mov     ax, [motext__chunkSplit__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     byte [es:bx], 8
; ---- chunkNext[c] = d
        mov     ax, [motext__chunkSplit__d]
        mov     bx, [motext__chunkSplit__c]
        shl     bx, 1                       ; word elements
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     [es:bx], ax
        ret

; ============================================== sub lineInsert ====

lineInsert:
; ---- if ( ln >= lineCount ) return
        mov     ax, [lineInsert__ln]
        mov     bx, [motext__lineCount]
        cmp     ax, bx
        jb      .L90                        ; unsigned >=
        ret
.L90:
; ---- lineSeek( ln, col )
        mov     ax, [lineInsert__ln]
        mov     [motext__lineSeek__ln], ax
        mov     ax, [lineInsert__col]
        mov     [motext__lineSeek__col], ax
        call    motext__lineSeek
; ---- c = seekChunk
        mov     ax, [motext__seekChunk]
        mov     [lineInsert__c], ax
; ---- off = seekOff
        mov     ax, [motext__seekOff]
        mov     [lineInsert__off], ax
; ---- if ( chunkUsed[c] == chunkSize ) {
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     al, [es:bx]
        cmp     al, 16                      ; byte operands, no widening
        je      .L95                        ; unsigned ==
        jmp     .L93
.L95:
; ---- if ( off == chunkSize && chunkNext[c] == 0 ) {
        mov     ax, [lineInsert__off]
        cmp     ax, 16
        je      .L98                        ; unsigned ==
        jmp     .L96
.L98:
        mov     ax, [lineInsert__c]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     ax, [es:bx]
        test    ax, ax
        jne     .L96                        ; unsigned ==
; ---- d = chunkTake()
        call    motext__chunkTake
        mov     ax, [motext__chunkTake__ret]
        mov     [lineInsert__d], ax
; ---- if ( d == 0 ) {
        test    ax, ax
        jne     .L100                       ; unsigned ==
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyChunks
        mov     byte [motext__whyNoRoom], 1
; ---- return
        ret
.L100:
; ---- chunkNext[c] = d
        mov     ax, [lineInsert__d]
        mov     bx, [lineInsert__c]
        shl     bx, 1                       ; word elements
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     [es:bx], ax
; ---- c = d
        mov     ax, [lineInsert__d]
        mov     [lineInsert__c], ax
; ---- off = 0
        mov     word [lineInsert__off], 0
        jmp     .L97
.L96:
; ---- chunkSplit( c )
        mov     ax, [lineInsert__c]
        mov     [motext__chunkSplit__c], ax
        call    motext__chunkSplit
; ---- if ( chunkUsed[c] == chunkSize ) return    // chunkSplit set noRoom
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     al, [es:bx]
        cmp     al, 16                      ; byte operands, no widening
        jne     .L103                       ; unsigned ==
        ret
.L103:
; ---- if ( off > chunkUsed[c] ) {
        mov     ax, [lineInsert__off]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     al, [es:bx]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jbe     .L106                       ; unsigned >
; ---- off -= chunkUsed[c]
        mov     ax, [lineInsert__off]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     al, [es:bx]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        pop     ax
        sub     ax, bx
        mov     [lineInsert__off], ax
; ---- c = chunkNext[c]
        mov     ax, [lineInsert__c]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     ax, [es:bx]
        mov     [lineInsert__c], ax
.L106:
.L97:
.L93:
; ---- atDst( c )
        mov     ax, [lineInsert__c]
        mov     [motext__atDst__c], ax
        call    motext__atDst
; ---- for ( u16 i = chunkUsed[c]; i > off; i-- ) {
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     al, [es:bx]
        xor     ah, ah                      ; u8 -> u16
        mov     [lineInsert__i], ax
.L109:
        mov     ax, [lineInsert__i]
        mov     bx, [lineInsert__off]
        cmp     ax, bx
        jbe     .L111                       ; unsigned >
; ---- dst[i] = dst[ i - 1 ]
        mov     ax, [lineInsert__i]
        dec     ax
        mov     bx, ax
        mov     dx, [motext__dstSeg]        ; segment of motext__dst
        mov     es, dx
        mov     al, [es:bx]
        mov     bx, [lineInsert__i]
        mov     dx, [motext__dstSeg]        ; segment of motext__dst
        mov     es, dx
        mov     [es:bx], al
.L110:
        dec     word [lineInsert__i]
        jmp     .L109
.L111:
; ---- dst[off] = ch
        mov     al, [lineInsert__ch]
        mov     bx, [lineInsert__off]
        mov     dx, [motext__dstSeg]        ; segment of motext__dst
        mov     es, dx
        mov     [es:bx], al
; ---- chunkUsed[c]++
        mov     ax, [lineInsert__c]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        inc     byte [es:bx]
; ---- lineLen[ln]++
        mov     ax, [lineInsert__ln]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [motext__lenSeg]        ; segment of motext__lineLen
        mov     es, dx
        inc     word [es:bx]
; ---- undoPush( opInsert, ln, col, ch )
        mov     byte [motext__undoPush__op], 1
        mov     ax, [lineInsert__ln]
        mov     [motext__undoPush__ln], ax
        mov     ax, [lineInsert__col]
        mov     [motext__undoPush__col], ax
        mov     al, [lineInsert__ch]
        mov     [motext__undoPush__ch], al  ; u8 -> u8, no widening
        call    motext__undoPush
        ret

; ============================================== sub lineAppend ====

lineAppend:
; ---- sub lineAppend( u16 ln, u8 ch ) => lineInsert( ln, lineLen[ln], ch )
        mov     ax, [lineAppend__ln]
        mov     [lineInsert__ln], ax
        mov     ax, [lineAppend__ln]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [motext__lenSeg]        ; segment of motext__lineLen
        mov     es, dx
        mov     ax, [es:bx]
        mov     [lineInsert__col], ax
        mov     al, [lineAppend__ch]
        mov     [lineInsert__ch], al        ; u8 -> u8, no widening
        call    lineInsert
        ret

; ============================================== sub motext__lineNew ====

motext__lineNew:
; ---- if ( lineCount >= lineLimit ) {
        mov     ax, [motext__lineCount]
        mov     bx, [motext__lineLimit]
        cmp     ax, bx
        jb      .L113                       ; unsigned >=
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyLines
        mov     byte [motext__whyNoRoom], 2
; ---- return
        ret
.L113:
; ---- lineHead[lineCount]   = chunkTake()
        call    motext__chunkTake
        mov     ax, [motext__chunkTake__ret]
        mov     bx, [motext__lineCount]
        shl     bx, 1                       ; word elements
        mov     dx, [motext__headSeg]       ; segment of motext__lineHead
        mov     es, dx
        mov     [es:bx], ax
; ---- lineLen[lineCount] = 0
        mov     ax, [motext__lineCount]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [motext__lenSeg]        ; segment of motext__lineLen
        mov     es, dx
        mov     word [es:bx], 0
; ---- lineCount++
        inc     word [motext__lineCount]
        ret

; ============================================== sub textInit ====

textInit:
; ---- lineCount  = 0
        mov     word [motext__lineCount], 0
; ---- chunkFree  = 0
        mov     word [motext__chunkFree], 0
; ---- chunkHigh  = 1
        mov     word [motext__chunkHigh], 1
; ---- chunkLimit = 0
        mov     word [motext__chunkLimit], 0
; ---- lineLimit  = 0
        mov     word [motext__lineLimit], 0
; ---- undoHead   = 0
        mov     word [motext__undoHead], 0
; ---- undoCount  = 0
        mov     word [motext__undoCount], 0
; ---- undoDone   = 0
        mov     word [motext__undoDone], 0
; ---- undoing    = false
        mov     byte [motext__undoing], 0
; ---- breakRun   = true
        mov     byte [motext__breakRun], 1
; ---- noRoom     = false
        mov     byte [motext__noRoom], 0
; ---- whyNoRoom  = whyNothing
        mov     byte [motext__whyNoRoom], 0
; ---- stepDepth  = 0
        mov     word [motext__stepDepth], 0
; ---- stepLost   = false
        mov     byte [motext__stepLost], 0
; ---- undoLost   = false
        mov     byte [motext__undoLost], 0
; ---- recBase = blockBase()
        call    blockBase
        mov     ax, [blockBase__ret]
        mov     [motext__recBase], ax
; ---- textBase = 0
        mov     word [motext__textBase], 0
; ---- if ( recBase == 0 ) {
        mov     ax, [motext__recBase]
        test    ax, ax
        jne     .L116                       ; unsigned ==
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyBlock
        mov     byte [motext__whyNoRoom], 3
; ---- return
        ret
.L116:
; ---- nextSeg  = recBase
        mov     ax, [motext__recBase]
        mov     [motext__nextSeg], ax
; ---- usedSeg  = nextSeg + nextParas
        add     ax, 3000
        mov     [motext__usedSeg], ax
; ---- headSeg  = usedSeg + usedParas
        add     ax, 1500
        mov     [motext__headSeg], ax
; ---- lenSeg   = headSeg + headParas
        add     ax, 1500
        mov     [motext__lenSeg], ax
; ---- textBase = lenSeg + lenParas
        add     ax, 1500
        mov     [motext__textBase], ax
; ---- if ( blockEnd() <= textBase ) {
        call    blockEnd
        mov     ax, [blockEnd__ret]
        mov     bx, [motext__textBase]
        cmp     ax, bx
        ja      .L119                       ; unsigned <=
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyBlock
        mov     byte [motext__whyNoRoom], 3
; ---- return
        ret
.L119:
; ---- room = blockEnd() - textBase
        call    blockEnd
        mov     ax, [blockEnd__ret]
        mov     bx, [motext__textBase]
        sub     ax, bx
        mov     [textInit__room], ax
; ---- chunkLimit = maxChunks
        mov     word [motext__chunkLimit], 24000
; ---- if ( room < chunkLimit ) chunkLimit = room
        mov     ax, [textInit__room]
        mov     bx, [motext__chunkLimit]
        cmp     ax, bx
        jae     .L122                       ; unsigned <
        mov     ax, [textInit__room]
        mov     [motext__chunkLimit], ax
.L122:
; ---- if ( chunkLimit < 2 ) {
        mov     ax, [motext__chunkLimit]
        cmp     ax, 2
        jae     .L125                       ; unsigned <
; ---- chunkLimit = 0
        mov     word [motext__chunkLimit], 0
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyBlock
        mov     byte [motext__whyNoRoom], 3
; ---- return
        ret
.L125:
; ---- lineLimit = textMaxLines
        mov     word [motext__lineLimit], 12000
; ---- lineNew()
        call    motext__lineNew
        ret

; ============================================== sub textLoad ====

textLoad:
; ---- undoing = true
        mov     byte [motext__undoing], 1
; ---- if ( ch == '\n' ) {
        mov     al, [textLoad__ch]
        cmp     al, 10                      ; byte operands, no widening
        jne     .L128                       ; unsigned ==
; ---- lineNew()
        call    motext__lineNew
        jmp     .L129
.L128:
; ---- } else if ( ch != '\r' ) {
        mov     al, [textLoad__ch]
        cmp     al, 13                      ; byte operands, no widening
        je      .L131                       ; unsigned !=
; ---- lineAppend( lineCount - 1, ch )
        mov     ax, [motext__lineCount]
        dec     ax
        mov     [lineAppend__ln], ax
        mov     al, [textLoad__ch]
        mov     [lineAppend__ch], al        ; u8 -> u8, no widening
        call    lineAppend
.L131:
.L129:
; ---- undoing = false
        mov     byte [motext__undoing], 0
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0

